{
  "name": "opencode-tss",
  "version": "1.1.0",
  "description": "Text-to-speech plugin for OpenCode — reads AI responses aloud on macOS using the native `say` command",
  "author": "Soulberto Lorenzo",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "module": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "src"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm --external @opencode-ai/plugin && tsc --emitDeclarationOnly",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/node": "^25.0.10",
    "typescript": "^5.7.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "tts",
    "text-to-speech",
    "macos",
    "say",
    "audio",
    "speech",
    "accessibility"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/slorenzot/opencode-tss.git"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "opencode-tss": "^1.0.0"
  }
}
